bool32 GymDecor_IsTypeUnlocked(u32 type)
{
    const struct GymDecorTypeUnlock *unlock;
    u32 i;
    if (type >= NUMBER_OF_MON_TYPES)
        return FALSE;
    if (FlagGet(FLAG_PALLET_GYM_AWARDED))
        return TRUE;
    unlock = &sTypeUnlocks[type];
    if (unlock->flag != 0 && FlagGet(unlock->flag))
        return TRUE;
    for (i = 0; i < ARRAY_COUNT(unlock->trainers); i++)
    {
        if (unlock->trainers[i] != 0 && HasTrainerBeenFought(unlock->trainers[i]))
            return TRUE;
    }
    return FALSE;
}

// Gym Trainer hack: "New GYM decorations available!" Counts the unlocked decorations (not the
// trainers) and returns TRUE once each time the count goes up (checked as the player walks,
// src/field_control_avatar.c). Nothing before the gym opens.
static u32 CountUnlockedDecor(void)
{
    u32 i, n = 0;
    for (i = 1; i < GYM_DECOR_COUNT; i++)
    {
        if (gGymDecor[i].category != GYM_DECOR_CAT_TRAINERS && gGymDecor[i].category != GYM_DECOR_CAT_TROPHIES
         && GymDecor_IsUnlocked(i))
            n++;
    }
    return n;
}

bool32 GymDecor_CheckNewUnlocks(void)
{
    u32 n;
    // (Pokémon Canvas: the National Pokédex comes with the Pokédex; older saves get it here)
    if (FlagGet(FLAG_SYS_POKEDEX_GET) && !IsNationalPokedexEnabled())
        EnableNationalPokedex();
    if (!FlagGet(FLAG_PALLET_GYM_OPEN))
        return FALSE;
    n = CountUnlockedDecor();
    if (n <= VarGet(VAR_GYM_DECOR_SEEN))
        return FALSE;
    VarSet(VAR_GYM_DECOR_SEEN, n);
    return TRUE;
}

// Special: the gym has just opened; what's unlocked now isn't news
void GymDecor_MarkUnlocksSeen(void)
{
    VarSet(VAR_GYM_DECOR_SEEN, CountUnlockedDecor());
}

bool32 GymDecor_IsUnlocked(u32 id)
{
    u32 category = gGymDecor[id].category;
    if (category >= GYM_DECOR_CAT_TYPE(0) && category < GYM_DECOR_CAT_TROPHIES && !GymDecor_IsTypeUnlocked(category - GYM_DECOR_CAT_TYPE(0)))
        return FALSE;
    return gGymDecor[id].unlockFlag == 0 || FlagGet(gGymDecor[id].unlockFlag);
}

// The gym's tileset has just been copied to video memory (src/fieldmap.c): the room's art goes
// in after it (src/gym_room.c)
extern const struct Tileset gTileset_PalletGym;

void GymDecor_PatchTilesetGfx(struct MapLayout const *mapLayout)
{
    if (mapLayout != NULL && mapLayout->secondaryTileset == &gTileset_PalletGym)
        GymRoom_OnTilesetLoaded();
}

u32 GymDecor_CountOwned(u32 id)
{
    // The battle stage is free and always in storage (one of it)
    // (and the gym's own floor and walls)
    if (id == GYM_DECOR_BATTLE_STAGE || (IsStyle(id) && gGymDecor[id].price == 0))
        return 1;
    if (IsStyle(id))
        return GetSave()->owned[id] ? 1 : 0;
    return GetSave()->owned[id];
}

// Where decoration `id` is placed in the gym (its top-left block), if it is
bool32 GymDecor_FindPlaced(u32 id, s32 *x, s32 *y)
{
    struct GymDecorSaveData *save = GetSave();
    u32 i;
    for (i = 0; i < save->numPlaced; i++)
    {
        if (save->placed[i].id == id && GYM_PLACEMENT_ROOM(&save->placed[i]) == ROOM_GYM)
        {
            *x = save->placed[i].x;
            *y = save->placed[i].y;
            return TRUE;
        }
    }
    return FALSE;
}

u32 GymDecor_CountPlaced(u32 id)
{
    struct GymDecorSaveData *save = GetSave();
    u32 i, n = 0;
    for (i = 0; i < save->numPlaced; i++)
    {
        if (save->placed[i].id == id)
            n++;
    }
    return n;
}

u32 GymDecor_CountAvailable(u32 id)
{
    if (IsStyle(id))
        return GymDecor_CountOwned(id);     // (used as often as you like)
    u32 owned = GymDecor_CountOwned(id), placed = GymDecor_CountPlaced(id);
    return owned > placed ? owned - placed : 0;
}

u32 GymDecor_NumPlaced(void)
{
    return GetSave()->numPlaced;
}

// The secret base space left after the decorations (used by src/gym_challenge.c)
void *GymDecor_GetSpareSaveSpace(u32 *size)
{
    *size = sizeof(((struct SaveBlock1 *)0)->secretBases) - sizeof(struct GymDecorSaveData);
    return (u8 *)gSaveBlock1Ptr->secretBases + sizeof(struct GymDecorSaveData);
}

void GymDecor_ClearAll(void)
{
    struct GymDecorSaveData *save = GetSave();
    memset(save, 0, sizeof(*save));
    save->magic = GYM_DECOR_SAVE_MAGIC;
}

static void Footprint(u32 id, u32 facing, s32 *w, s32 *h)
{
    const struct GymDecor *d = &gGymDecor[id];
    if (facing >= d->numFacings)
        facing = 0;
    *w = d->facings[facing].width;
    *h = d->facings[facing].height;
}

// The placement covering (x, y) in this room, or -1
static s32 FindPlacementAt(s32 x, s32 y)
{
    struct GymDecorSaveData *save = GetSave();
    s32 i, w, h;
    u32 room = CurrentRoom();
    for (i = save->numPlaced - 1; i >= 0; i--)
    {
        const struct GymDecorPlacement *p = &save->placed[i];
        if (GYM_PLACEMENT_ROOM(p) != room || p->id >= GYM_DECOR_COUNT)
            continue;
        Footprint(p->id, GYM_PLACEMENT_FACING(p), &w, &h);
        if (x >= p->x && x < p->x + w && y >= p->y && y < p->y + h)
            return i;
    }
    return -1;
}

// Pokémon Canvas: the decoration placed in the gym (or a room) at a map position (MAP_OFFSET
// included), or GYM_DECOR_COUNT (src/field_control_avatar.c: the Drink Machine can be talked to)
u32 GymDecor_IdAtMapPos(s32 x, s32 y)
{
    s32 i;
    if (!GymDecor_InRoom())
        return GYM_DECOR_COUNT;
    i = FindPlacementAt(x - MAP_OFFSET, y - MAP_OFFSET);
    return i < 0 ? GYM_DECOR_COUNT : GetSave()->placed[i].id;
}

static bool32 InEditAreaOf(u32 room, s32 x, s32 y)
{
    const struct GymRoomInfo *info = GymRoom_GetInfo(room);
    if (x < info->edit[0] || x > info->edit[2] || y < info->edit[1] || y > info->edit[3])
        return FALSE;
    if (x >= info->reserved[0] && x <= info->reserved[2] && y >= info->reserved[1] && y <= info->reserved[3])
        return FALSE;
    return !GymRoom_IsDoorFront(room, x, y);       // (the way through a doorway stays clear)
}

static bool32 InEditArea(s32 x, s32 y)
{
    return InEditAreaOf(CurrentRoom(), x, y);
}

bool32 GymDecor_CanPlace(u32 id, u32 facing, s32 x, s32 y)
{
    const struct GymDecor *d = &gGymDecor[id];
    s32 cx, cy, w, h;
    if (id >= GYM_DECOR_COUNT || IsStyle(id) || facing >= d->numFacings)
        return FALSE;
    if (GymDecor_CountAvailable(id) == 0 || GetSave()->numPlaced >= GYM_DECOR_MAX_PLACED)
        return FALSE;
    if (d->category == GYM_DECOR_CAT_TRAINERS && GymDecor_CountPlacedTrainers() >= GYM_PRACTICE_SLOTS)
        return FALSE;
    if (MainRoomOnly(id) && CurrentRoom() != ROOM_GYM)
        return FALSE;
    Footprint(id, facing, &w, &h);
    for (cy = y; cy < y + h; cy++)
    {
        for (cx = x; cx < x + w; cx++)
        {
            if (!InEditArea(cx, cy) || FindPlacementAt(cx, cy) >= 0)
                return FALSE;
        }
    }
    // (pieces can stand in front of a wall's face, where it shows behind them; not rugs or pools)
    return GymRoom_PieceFitsWalls(id, facing, x, y);
}

bool32 GymDecor_Place(u32 id, u32 facing, s32 x, s32 y)
{
    struct GymDecorSaveData *save = GetSave();
    struct GymDecorPlacement *p;
    if (!GymDecor_CanPlace(id, facing, x, y))
        return FALSE;
    p = &save->placed[save->numPlaced++];
    p->id = id;
    p->x = x;
    p->y = y;
    p->room = (CurrentRoom() << 2) | facing;
    return TRUE;
}

bool32 GymDecor_RemoveAt(s32 x, s32 y)
{
    u32 id, facing;
    return GymDecor_TakeAt(x, y, &id, &facing);
}

// Puts away the piece covering (x, y), saying which it was and the way it faced
bool32 GymDecor_TakeAt(s32 x, s32 y, u32 *id, u32 *facing)
{
    struct GymDecorSaveData *save = GetSave();
    s32 i = FindPlacementAt(x, y);
    if (i < 0)
        return FALSE;
    *id = save->placed[i].id;
    *facing = GYM_PLACEMENT_FACING(&save->placed[i]);
    memmove(&save->placed[i], &save->placed[i + 1], (save->numPlaced - i - 1) * sizeof(save->placed[0]));
    save->numPlaced--;
    return TRUE;
}

// Pieces placed where nothing can go any more (older saves had no side walls; a doorway that's
// opened needs the way through it clear) go back to storage
static void PutAwayMisplaced(void)
{
    struct GymDecorSaveData *save = GetSave();
    s32 i, x, y, w, h;
    if (save->numPlaced > GYM_DECOR_MAX_PLACED)
        save->numPlaced = 0;
    for (i = save->numPlaced - 1; i >= 0; i--)
    {
        const struct GymDecorPlacement *p = &save->placed[i];
        u32 room = GYM_PLACEMENT_ROOM(p);
        bool32 ok = p->id < GYM_DECOR_COUNT && room < GYM_ROOM_COUNT && !(room != ROOM_GYM && MainRoomOnly(p->id));
        if (ok)
        {
            Footprint(p->id, GYM_PLACEMENT_FACING(p), &w, &h);
            for (y = p->y; y < p->y + h && ok; y++)
                for (x = p->x; x < p->x + w && ok; x++)
                    ok = InEditAreaOf(room, x, y);
        }
        if (!ok)
        {
            memmove(&save->placed[i], &save->placed[i + 1], (save->numPlaced - i - 1) * sizeof(save->placed[0]));
            save->numPlaced--;
        }
    }
}

// Map script (ON_LOAD): the room, with everything the player has placed and painted
void GymDecor_DrawRoom(void)
{
    sEditing = FALSE;
    sHudWindowId = WINDOW_NONE;
    PutAwayMisplaced();
    GymRoom_Load();
}

